# fn attribution maps for fn_map field in _build_stripped_injected_deltas
_SYS_FN: dict[int, str] = {1: '_apply_system_passes', 2: '_apply_system_passes', 3: '_strip_sys3'}
_FIELD_STRIP_FN: dict[str, str] = {
