}
_MSG_CODE_TO_FN: dict[str, str] = {
    'RS':  '_apply_role_system_strip',
    'REJ': '_apply_first_pass',  'TN':  '_apply_first_pass',
    'NAG': '_apply_first_pass',  'DEF': '_apply_first_pass',
